css:
.button {
  --😀: #644dff;
  --😀😀: #4836bb;
  --😀😀😀: #654dff63;
  cursor: pointer;
  width: 184px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  font-size: 1.125em;
  font-weight: 800;
  letter-spacing: 2px;
  color: #fff;
  background: var(--😀);
  border: 2px solid var(--😀😀);
  border-radius: 75rem;
  box-shadow: 0 5px 0 var(--😀😀);

  transition: all 0.1s ease;
}

.button:active {
  letter-spacing: 0px;
  transform: translateY(8px);
  box-shadow: 0 0 0 var(--😀😀😀);
}
